# Mapeo corregido: varias variantes del excel colapsan al mismo TipoCliente real
MAPEO_TIPO_CLIENTE = {
    'gastronomia': 'Gastronomico',
    'gastronomicos': 'Gastronomico',
    'distribucion': 'Distribuidor',
    'distribuidores': 'Distribuidor',
}


class Command(BaseCommand):
    help = "Corrige el tipo_cliente y lista_precios de los clientes importados con el mapeo viejo"

    def handle(self, *args, **options):
        corregidos = 0
        sin_lista_vigente = []
        no_encontrados = []

        for data in CLIENTES_DATA:
            cuit = data['cuit']
            if not cuit:
                continue

            try:
                cliente = Cliente.objects.get(cuit=cuit)
            except Cliente.DoesNotExist:
                no_encontrados.append(data['razon_social'])
                continue

            valor_excel = data['tipo_cliente'].strip().lower()
            nombre_real = MAPEO_TIPO_CLIENTE.get(valor_excel)
            if nombre_real is None:
                continue

            try:
                tipo_cliente = TipoCliente.objects.get(nombre__iexact=nombre_real)
            except TipoCliente.DoesNotExist:
                sin_lista_vigente.append(f"{cliente.razon_social} (TipoCliente '{nombre_real}' no existe)")
                continue

            lista_vigente = (
                ListaPrecios.objects
                .filter(tipo_cliente=tipo_cliente)
                .order_by('-fecha')
                .first()
            )

            cliente.tipo_cliente = tipo_cliente
            cliente.lista_precios = lista_vigente
            cliente.save(update_fields=['tipo_cliente', 'lista_precios'])
            corregidos += 1

            if lista_vigente is None:
                sin_lista_vigente.append(f"{cliente.razon_social} (tipo_cliente '{nombre_real}' sin ninguna ListaPrecios vigente)")

        self.stdout.write(self.style.SUCCESS(f'Clientes corregidos: {corregidos}'))
        if no_encontrados:
            self.stdout.write(self.style.WARNING(f'No encontrados por CUIT ({len(no_encontrados)}):'))
            for n in no_encontrados:
                self.stdout.write(f'  - {n}')
        if sin_lista_vigente:
            self.stdout.write(self.style.WARNING(f'Sin ListaPrecios vigente ({len(sin_lista_vigente)}):'))
            for s in sin_lista_vigente:
                self.stdout.write(f'  - {s}')
